    surf = mix(surf, vec3(0.9, 0.92, 0.95) * (0.10 + 0.90 * dayF), cloud * 0.55);

    surf += night * vec3(1.0, 0.82, 0.55) * pow(1.0 - dayF, 1.7) * (1.0 - cloud * 0.75) * 1.7;

